effect.shader:
void main(){
  vec2 uv = acScreenNorm;
  vec4 src = texture2DCv(inputImg.texture, uv);
  float a = max(src.a, 1e-4);
  vec3 c = src.rgb / a;
  float l0 = gmLum(c);
  vec2 px = vec2(edgeWidth / max(acScreenSize.x, 1.0), edgeWidth / max(acScreenSize.y, 1.0));
  float l1 = gmLum(texture2DCv(inputImg.texture, uv + vec2(px.x, 0.0)).rgb / max(texture2DCv(inputImg.texture, uv + vec2(px.x, 0.0)).a, 1e-4));
  float l2 = gmLum(texture2DCv(inputImg.texture, uv - vec2(px.x, 0.0)).rgb / max(texture2DCv(inputImg.texture, uv - vec2(px.x, 0.0)).a, 1e-4));
  float l3 = gmLum(texture2DCv(inputImg.texture, uv + vec2(0.0, px.y)).rgb / max(texture2DCv(inputImg.texture, uv + vec2(0.0, px.y)).a, 1e-4));
  float l4 = gmLum(texture2DCv(inputImg.texture, uv - vec2(0.0, px.y)).rgb / max(texture2DCv(inputImg.texture, uv - vec2(0.0, px.y)).a, 1e-4));
  float edgeAmt = smoothstep(0.04, 0.55, abs(l0 - l1) + abs(l0 - l2) + abs(l0 - l3) + abs(l0 - l4));
  vec3 toned = pow(clamp(c, 0.0, 1.0), vec3(1.0 / max(gamma, 0.05)));
  float n = max(steps, 2.0) - 1.0;
  vec3 poster = floor(toned * n + 0.5) / n;
  poster = mix(poster, inkColor.rgb, edgeAmt * edge);
  vec3 col = mix(c, poster, mixAmt);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0) * src.a, src.a);
}
